INSERT INTO "description" VALUES('P1','en','URL of an equivalent property or class in another schema (Wikidata, CIDOC CRM, Linked Art, LIDO).');
INSERT INTO "description" VALUES('P10','en','Material the artwork is made from.');
INSERT INTO "description" VALUES('P11','en','Height in centimetres.');
INSERT INTO "description" VALUES('P12','en','Width in centimetres.');
INSERT INTO "description" VALUES('P13','en','Depth in centimetres.');
INSERT INTO "description" VALUES('P14','en','Identifier of the physical object in a collection.');
INSERT INTO "description" VALUES('P15','en','Catalogue code or accession code associated with the artwork.');
INSERT INTO "description" VALUES('P16','en','Current location (collection or venue) of the artwork, or venue of an exhibition.');
INSERT INTO "description" VALUES('P17','en','URL of an image of the artwork.');
INSERT INTO "description" VALUES('P18','en','Series or related group to which the artwork belongs.');
INSERT INTO "description" VALUES('P19','en','Subject or motif depicted in the artwork.');
INSERT INTO "description" VALUES('P2','en','Identifier of the record in the source CSV files, used to make loads repeatable.');
INSERT INTO "description" VALUES('P20','en','Iconclass notation for a subject depicted in the artwork.');
INSERT INTO "description" VALUES('P21','en','Exhibition in which the artwork was shown. Catalogue details are added as qualifiers.');
INSERT INTO "description" VALUES('P22','en','Current owner or holder of the artwork.');
INSERT INTO "description" VALUES('P23','en','Wikimedia Commons category that documents or illustrates the artwork.');
INSERT INTO "description" VALUES('P24','en','Identifier of the matching Wikidata item.');
INSERT INTO "description" VALUES('P25','en','Identifier in the Gemeinsame Normdatei.');
INSERT INTO "description" VALUES('P26','en','Identifier in the Getty Art & Architecture Thesaurus.');
INSERT INTO "description" VALUES('P27','en','Date the exhibition opened.');
INSERT INTO "description" VALUES('P28','en','Date the exhibition closed.');
INSERT INTO "description" VALUES('P3','en','Main class of the artwork, usually a work of art or specific type of object.');
INSERT INTO "description" VALUES('P32','en','Number of the item in the exhibition catalogue.');
INSERT INTO "description" VALUES('P33','en','Page(s) of the exhibition catalogue on which the item is listed or reproduced.');
INSERT INTO "description" VALUES('P34','en','Title under which the artwork was shown, if different from its current title.');
INSERT INTO "description" VALUES('P35','en','Free-text note.');
INSERT INTO "description" VALUES('P36','en','Date of creation exactly as given in the source, for example 1972-73 or 1970s.');
INSERT INTO "description" VALUES('P37','en','Object type exactly as given in the source, for example Super-8 film loop (originally 16 mm).');
INSERT INTO "description" VALUES('P38','en','Materials and technique exactly as given in the source, for example Ink-jet on canvas; hand lettering and acrylic paint.');
INSERT INTO "description" VALUES('P39','en','Subtitle of the catalogue as printed.');
INSERT INTO "description" VALUES('P4','en','More specific type of the artwork, such as painting, print, sculpture, or installation.');
INSERT INTO "description" VALUES('P40','en','Person who wrote texts in the catalogue.');
INSERT INTO "description" VALUES('P41','en','Publishing house or institution that published the catalogue.');
INSERT INTO "description" VALUES('P42','en','Year or date when the catalogue was published.');
INSERT INTO "description" VALUES('P43','en','13-digit International Standard Book Number.');
INSERT INTO "description" VALUES('P44','en','Identifier (IDN) of the catalogue record in the German National Library.');
INSERT INTO "description" VALUES('P45','en','Web page that describes the catalogue, for example its record in the German National Library.');
INSERT INTO "description" VALUES('P46','en','Exhibition that the catalogue documents. Inverse of ''Exhibition catalogue''.');
INSERT INTO "description" VALUES('P47','en','Catalogue that documents the exhibition. Inverse of ''Catalogue of''.');
INSERT INTO "description" VALUES('P48','en','Catalogue in which the artwork appears, for example the catalogue the record was taken from. Optional qualifiers give the scan page and region so that the extraction can be reviewed.');
INSERT INTO "description" VALUES('P49','en','Sequence number of the scanned page (first scan page = 1) on which the artwork was found. Not the printed page number. Qualifier of ''Appears in catalogue''.');
INSERT INTO "description" VALUES('P5','en','Title of the artwork or exhibition.');
INSERT INTO "description" VALUES('P50','en','Rectangle on the scanned page where the entry is, as a W3C Media Fragment, for example xywh=percent:10,20,40,8 (x, y, width, height in percent of the page). Qualifier of ''Appears in catalogue''.');
INSERT INTO "description" VALUES('P51','en','How the entry was found, for example ''plan-c qwen3-vl:8b'', ''plan-b hocr'' or ''manual''. Qualifier of ''Appears in catalogue''.');
INSERT INTO "description" VALUES('P52','en','Result of the manual check: unreviewed, confirmed, corrected or rejected. Qualifier of ''Appears in catalogue''.');
INSERT INTO "description" VALUES('P6','en','Person who made the artwork.');
INSERT INTO "description" VALUES('P7','en','Date the artwork was created.');
INSERT INTO "description" VALUES('P8','en','Main subject or motif represented in the artwork.');
INSERT INTO "description" VALUES('P9','en','Material or materials used to make the artwork.');
